export interface Ball {
  x: number
  y: number
  vx: number
  vy: number
  r: number
}

export function make(): Ball {
  return {
    x: Math.random() * 380 + 10,
    y: Math.random() * 280 + 10,
    vx: (Math.random() - 0.5) * 4,
    vy: (Math.random() - 0.5) * 4,
    r: 10,
  }
}

export function step(balls: Ball[]): void {
  const gravity = 0.2
  const w = 400
  const h = 300

  for (let i = 0; i < balls.length; i++) {
    const b = balls[i]
    b.vy += gravity
    b.x += b.vx
    b.y += b.vy

    if (b.x - b.r < 0) {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if (b.x + b.r > w) {
      b.x = w - b.r
      b.vx = -Math.abs(b.vx)
    }
    if (b.y - b.r < 0) {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if (b.y + b.r > h) {
      b.y = h - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i]
      const b2 = balls[j]
      const dx = b2.x - b1.x
      const dy = b2.y - b1.y
      const dist = Math.sqrt(dx * dx + dy * dy)
      const minDist = b1.r + b2.r

      if (dist < minDist) {
        const temp1x = b1.vx
        const temp1y = b1.vy
        b1.vx = b2.vx
        b1.vy = b2.vy
        b2.vx = temp1x
        b2.vy = temp1y

        const overlap = minDist - dist
        const nx = dx / dist
        const ny = dy / dist
        b1.x -= (overlap / 2) * nx
        b1.y -= (overlap / 2) * ny
        b2.x += (overlap / 2) * nx
        b2.y += (overlap / 2) * ny
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]): void {
  const ctx = canvas.getContext('2d')
  if (!ctx) return

  ctx.fillStyle = '#fff'
  ctx.fillRect(0, 0, canvas.width, canvas.height)

  ctx.fillStyle = '#3b82f6'
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

