use "./sim.ts" { make, step, draw }

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv

  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    requestAnimationFrame(tick)
  }

  fn addBall() {
    balls = [...balls, make()]
  }

  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
  }

  mount {
    reset()
    requestAnimationFrame(tick)
  }

  column gap=4 pad=4 {
    title "Simulación de Pelotas"

    canvas ref=cv id="sim" width=400 height=300 style="border: 2px solid #ccc; background: white;"

    row gap=2 {
      button "Agregar" -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> paused = !paused
      button "Reiniciar" -> reset()
    }

    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
  }
}

