interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

const W = 400;
const H = 300;
const RADIUS = 10;
const GRAVITY = 0.2;

export function make(): Ball {
  return {
    x: Math.random() * (W - 2 * RADIUS) + RADIUS,
    y: Math.random() * (H - 2 * RADIUS) + RADIUS,
    vx: (Math.random() - 0.5) * 4,
    vy: (Math.random() - 0.5) * 4,
    r: RADIUS,
  };
}

export function step(balls: Ball[]): void {
  // Apply gravity
  for (const b of balls) {
    b.vy += GRAVITY;
  }

  // Update positions
  for (const b of balls) {
    b.x += b.vx;
    b.y += b.vy;
  }

  // Collision with walls
  for (const b of balls) {
    if (b.x - b.r < 0) {
      b.x = b.r;
      b.vx = -b.vx;
    }
    if (b.x + b.r > W) {
      b.x = W - b.r;
      b.vx = -b.vx;
    }
    if (b.y - b.r < 0) {
      b.y = b.r;
      b.vy = -b.vy;
    }
    if (b.y + b.r > H) {
      b.y = H - b.r;
      b.vy = -b.vy;
    }
  }

  // Elastic collision between balls
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i];
      const b2 = balls[j];
      const dx = b2.x - b1.x;
      const dy = b2.y - b1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < b1.r + b2.r) {
        // Swap velocities for elastic collision
        const temp = b1.vx;
        b1.vx = b2.vx;
        b2.vx = temp;

        const temp2 = b1.vy;
        b1.vy = b2.vy;
        b2.vy = temp2;

        // Separate balls to avoid sticking
        const overlap = b1.r + b2.r - dist;
        const nx = dx / dist;
        const ny = dy / dist;
        const sep = overlap / 2 + 0.5;
        b1.x -= nx * sep;
        b1.y -= ny * sep;
        b2.x += nx * sep;
        b2.y += ny * sep;
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, W, H);

  for (const b of balls) {
    ctx.fillStyle = "#3b82f6";
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}
